import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        // The JSON array holds [name, price, weight] rows: collect its strings and numbers in order.
        List<String> tokens = new ArrayList<>();
        int len = in.length();
        for (int i = 0; i < len; i++) {
            char c = in.charAt(i);
            if (c == '"') {
                StringBuilder sb = new StringBuilder();
                for (i++; i < len && in.charAt(i) != '"'; i++) {
                    if (in.charAt(i) == '\\') i++;
                    sb.append(in.charAt(i));
                }
                tokens.add(sb.toString());
            } else if (c == '-' || Character.isDigit(c)) {
                int j = i;
                while (j + 1 < len && Character.isDigit(in.charAt(j + 1))) j++;
                tokens.add(Long.toString(Long.parseLong(in.substring(i, j + 1))));
                i = j;
            }
        }
        HashMap<String, Integer> count = new HashMap<>();
        for (int i = 0; i + 2 < tokens.size(); i += 3)
            count.merge(tokens.get(i) + "|" + tokens.get(i + 1) + "|" + tokens.get(i + 2), 1, Integer::sum);
        long answer = 0;
        for (int c : count.values()) if (c > 1) answer += c;
        System.out.println(answer);
    }
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	var rows [][3]json.RawMessage // [name, price, weight]
	if err := json.Unmarshal(data, &rows); err != nil {
		panic(err)
	}
	type product struct {
		name          string
		price, weight int
	}
	count := map[product]int{}
	for _, row := range rows {
		var p product
		json.Unmarshal(row[0], &p.name)
		json.Unmarshal(row[1], &p.price)
		json.Unmarshal(row[2], &p.weight)
		count[p]++
	}
	answer := 0
	for _, c := range count {
		if c > 1 {
			answer += c
		}
	}
	fmt.Println(answer)
}
